scripts.lcg_iterate:
def solve(inputs: dict) -> float:
    s = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = int(inputs['K'])
    for _ in range(k):
        s = (a * s + b) % m
    return float(s)

scripts.luhn_sum:
def solve(inputs: dict) -> float:
    n = int(inputs['N'])
    digits = [int(d) for d in str(n)]
    total = 0
    # Reading from the right, double every second digit (positions 2, 4, 6, ... from right)
    for i, d in enumerate(reversed(digits)):
        if (i + 1) % 2 == 0:  # every second digit from right (i=1, 3, 5, ...)
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return float(total)

scripts.cf_numerator:
def solve(inputs: dict) -> float:
    # Continued fraction numerator
    # Terms passed as individual t0, t1, t2, ... or we hardcode
    terms = [int(inputs[f't{i}']) for i in range(int(inputs['n']))]
    p_prev2 = 1  # p_{-1}
    p_prev1 = terms[0]  # p_0
    if len(terms) == 1:
        return float(p_prev1)
    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr
    return float(p_prev1)

